  "objectifGeneral": "S'entraîner à mobiliser les connaissances sur les Trente Glorieuses en identifiant leurs caractéristiques, leurs transformations et leurs limites.",
  "notionsPivots": [
    "la croissance économique",
    "la société de consommation",
    "les Trente Glorieuses",
    "le baby-boom",
    "la tertiarisation de l'économie",
    "les inégalités sociales"
  ],
