        {
          "titre": "Frise des Trente Glorieuses",
          "objectif": "Associer des événements à leurs dates",
          "module": "Timeline",
          "palier": "decouverte",
          "duree": 10,
          "consigne": "Placez les événements proposés sur la frise chronologique en les associant à leur date exacte."
        },
        {
          "titre": "Acteurs économiques et politiques",
          "objectif": "Identifier les principaux acteurs des Trente Glorieuses",
