        },
        {
          "titre": "Les transformations de la société",
          "objectif": "Classer les changements sociaux selon leur nature",
          "module": "SortParagraphs",
          "palier": "transfert",
          "duree": 20,
          "consigne": "Triez les affirmations proposées selon qu'elles illustrent une transformation économique, sociale ou culturelle des Trente Glorieuses."
        }
      ]
    },
    {
      "titre": "Évaluer les limites du modèle",
      "objectif": "Repérer et expliquer les limites des Trente Glorieuses",
      "cartes": [
        {
          "titre": "Quiz sur les limites",
          "objectif": "Reconnaître les limites des Trente Glorieuses",
          "module": "QuizSetQCM",
          "palier": "entrainement",
          "duree": 15,
          "consigne": "Répondez aux questions à choix multiples sur les limites économiques, sociales et environnementales des Trente Glorieuses."
        },
        {
          "titre": "Production écrite : les ombres des Trente Glorieuses",
          "objectif": "Rédiger un texte argumenté sur les limites",
          "module": "Essay",
          "palier": "transfert",
          "duree": 25,
          "consigne": "Rédigez un paragraphe expliquant une limite des Trente Glorieuses en utilisant au moins trois notions pivots de la liste."
        }
      ]
    }
  ]
}

